async function openHistory(key,order,date){
 if(!allowed()||stock)return;key=resolverChaveCliente(key);if(typeof carregarClassificacoesHistoricas==='function'){try{bairePurchaseHistory.historicalMetadata=await carregarClassificacoesHistoricas();}catch(error){alert(error.message);return;}}
 if(!manager()&&typeof clienteReservadoIris==='function'&&clienteReservadoIris(key+' '+(clientMap()[key]?.name||'')))return;
 const source=typeof pedidosParaHistoricoCliente==='function'?pedidosParaHistoricoCliente():vendasParaAnalise();
 const v=source.find(v=>resolverChaveCliente(v.cliente)===key&&String(v.pedido||'')===String(order)&&v.data===date);if(!v){alert('Pedido não encontrado. Atualize o histórico e tente novamente.');return;}
 shell();document.getElementById('bofModal').hidden=false;view='new';
 const original=historyOrderData(v,clientMap()[key]||{},key);editing=original;editing.loadingNotes=true;render();loadProducts();
 try{const shared=await readSharedOrder(original.sentOrderId||orderKey(order));if(shared&&editing===original){Object.assign(editing,shared,{sentOrderId:shared.id,id:original.id,originalOrder:shared.orderNumber,originalTotal:shared.total,amountsEdited:false,savedNotes:shared.notes||'',expectedVersion:Number(shared.deliveryVersion)||0,sharedRecord:true});}}catch(error){if(editing===original)editing.notesLoadError=error.message;}finally{if(editing===original){editing.loadingNotes=false;render();if(editing.notesLoadError)document.getElementById('bofMessage').textContent=editing.notesLoadError;}}
}
function recalc(){collect();document.getElementById('bofTotal').textContent=money(total(editing));document.querySelectorAll('[data-bof-item]').forEach((row,i)=>row.querySelector('[data-line]').textContent=money(lineTotal(editing.items[i])));}
function render(){
 document.querySelectorAll('[data-bof-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.bofTab===view)));
 const body=document.getElementById('bofBody');document.getElementById('bofHeaderPrint').disabled=!editing;
 if(view==='pending'){refreshQueue();return;}
 if(view!=='new'){const list=drafts();body.innerHTML=`<h3>${view==='drafts'?'Rascunhos neste navegador':view==='pending'?'Controle de entregas':'Gestão de pedidos'}</h3><p class="bof-subtle">Rascunhos salvos neste navegador. Use Salvar e imprimir para enviar ao Controle de entregas; reimprimir um pedido confirmado não cria outro.</p>${view==='manage'?'<div class="bof-grid">'+field('searchOrder','Pedido')+field('searchClient','Cliente')+field('searchSeller','Vendedor')+'<label>Status<select disabled><option>Todos</option><option>Aberto</option><option>Saiu para entrega</option><option>Entregue</option><option>Lançado</option></select></label></div>':''}<div class="bof-scroll"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Vendedor</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${list.length?list.map((o,i)=>`<tr><td>${e(o.orderNumber||o.originalOrder||('Rascunho '+(i+1)))}</td><td>${e(o.client)}</td><td>${e(o.date)}</td><td>${e(o.seller)}</td><td>${money(total(o))}</td><td>${o.sentOrderId?'Enviado ao Controle de entregas':'Rascunho — ainda não enviado'}</td><td><button onclick="BaireOrderForms.edit('${e(o.id)}')">Abrir pedido</button> <button onclick="BaireOrderForms.printDraft('${e(o.id)}')">🖨 Salvar e imprimir</button></td></tr>`).join(''):'<tr><td colspan="7">Nenhum rascunho salvo neste navegador.</td></tr>'}</tbody></table></div>${view==='drafts'?'':view==='manage'?managementFields():'<h4>Separação pela Estela</h4><p>O número, cliente, data, produtos e quantidades virão do Baire Vendas. A seleção de marcas e lotes usará o registro de vendas atual.</p><button disabled>Escolher marcas / lotes — aguardando integração</button>'}`;return;}
 const o=editing;body.innerHTML=`<h3>Pedido de venda</h3>${orderEditNotice(o)}${historicalAuditHTML(o)}<div class="bof-grid">${field('date','Data',o.date,'date')}${field('orderNumber','Número do pedido',o.orderNumber??o.originalOrder??'')}${orderStatusHTML(o)}<div id="bof-status-editor" hidden class="bof-wide"><label>Alterar status do rascunho<select id="bof-nextStatus">${statuses.map(v=>`<option${v===(o.status||'Aberto')?' selected':''}>${e(v)}</option>`).join('')}</select></label><button type="button" onclick="BaireOrderForms.confirmStatus()">Aplicar ao rascunho</button><small>Conferência local: nenhum pedido real será alterado. Lançado significa registrado no Conta Azul, não necessariamente pago.</small></div>${clientField(o)}${selectField('saleClass','Classe de venda',classes,o.saleClass)}${selectField('nfRequired','Nota fiscal',['Sim','Não'],o.nfRequired)}${field('invoice','Número da nota fiscal de venda',o.invoice)}<label class="bof-wide">Descrição para a comanda<textarea id="bof-description">${e(o.description)}</textarea></label></div>${maintenanceHTML(o,'bof-maint',true)}${o.editingFromQueue||historicalClassEditable(o)?fullDeliveryFields(o):''}<h4>Produtos vendidos</h4><p id="bofProductNotice" class="bof-subtle" role="status">${e(productError)||(products.length+' produto(s) cadastrado(s). Digite modelo ou descrição para escolher.')}</p><datalist id="bofProductList">${productListHTML()}</datalist><div class="bof-scroll"><table><thead><tr><th>Produto / modelo</th><th style="width:100px">Quantidade</th><th style="width:140px">Valor unitário</th><th style="width:120px">Total</th><th></th></tr></thead><tbody>${o.items.map((i,n)=>`<tr data-bof-item><td><input data-product value="${e(i.product)}" list="bofProductList" autocomplete="off" placeholder="Digite modelo ou descrição" aria-label="Produto ${n+1}"></td><td><input data-qty type="number" min="1" step="1" value="${i.qty}" oninput="BaireOrderForms.recalc()"></td><td><input data-unit type="number" min="0" step="0.01" value="${i.unit??''}" oninput="BaireOrderForms.recalc()"></td><td data-line>${i.unit==null&&i.total==null?'—':money(lineTotal(i))}</td><td><button onclick="BaireOrderForms.removeItem(${n})">×</button></td></tr>`).join('')}</tbody></table></div><button onclick="BaireOrderForms.addItem()">+ Produto</button><p class="bof-total">Total do pedido: <strong id="bofTotal">${money(total(o))}</strong></p><h4>Pagamento</h4><div class="bof-grid">${selectField('payment','Forma de pagamento',payments,o.payment)}${field('term','Prazo de pagamento',o.term)}${field('due','Vencimento',o.due,'date')}</div><h4>Faturas / parcelas</h4><div class="bof-scroll"><table><thead><tr><th>Tipo</th><th>Vencimento</th><th>Valor</th><th></th></tr></thead><tbody>${o.installments.map((i,n)=>`<tr data-bof-installment><td><input data-paytype value="${e(i.type)}"></td><td><input data-due type="date" value="${e(i.due)}"></td><td><input data-payvalue type="number" min="0" step=".01" value="${i.value}"></td><td><button onclick="BaireOrderForms.removePayment(${n})">×</button></td></tr>`).join('')}</tbody></table></div><button onclick="BaireOrderForms.addPayment()">+ Parcela</button><div class="bof-grid"><label class="bof-wide">Anotação / instruções para entrega<textarea id="bof-notes">${e(o.notes)}</textarea></label></div><div class="bof-actions"><button onclick="BaireOrderForms.save()">Salvar</button><button onclick="BaireOrderForms.print()">${o.originalOrder||o.sentOrderId?'🖨 Reimprimir pedido':'🖨 Imprimir pedido'}</button></div><p id="bofMessage" role="status"></p>`;lockHistoricalOrder();
}
