// Shared handoff: one immutable request per order number; stock changes only in the existing separation form.
const ORDER_PREFIX='baire_order_pending_v1_';
let orderSending=false,queueRecords=[],queueBusy=false,queueRefreshRequested=false,activeStockOrder=null,stockRegisterBusy=false;
const orderKey=number=>ORDER_PREFIX+encodeURIComponent(String(number||'').trim().toUpperCase());
function canReceiveOrders(){return stock&&!!window.baireLoginAtual?.()&&(manager()||window.baireLoginPode?.('vendas')===true);}
function orderPayload(o){
 const number=String(o.orderNumber||'').trim();
 if(!/^[A-Za-z0-9./-]{1,40}$/.test(number))throw Error('Preencha o número do pedido (até 40 caracteres, sem espaços).');
 if(!o.client?.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(o.date||''))throw Error('Confira cliente e data do pedido.');
 if(!o.items?.length||o.items.some(i=>!i.product?.trim()||!Number.isInteger(i.qty)||i.qty<1||!Number.isFinite(i.unit)||i.unit<0))throw Error('Confira os produtos, quantidades e valores unitários.');
 const base={orderNumber:number,date:o.date,clientKey:o.clientKey||'',client:o.client,contact:o.contact||'',phone:o.phone||'',address:o.address||'',city:o.city||'',neighborhood:o.neighborhood||'',seller:o.seller||'',saleClass:o.saleClass||'',nfRequired:o.nfRequired||'',invoice:o.invoice||'',payment:o.payment||'',term:o.term||'',due:o.due||'',description:o.description||'',notes:o.notes||'',items:o.items.map(i=>({product:i.product.trim(),qty:i.qty,unit:i.unit,...(i.total!=null?{total:i.total}:{})})),installments:o.installments||[],total:total(o),...(isMaintenance(o)?{maintenance:normalizeMaintenance(o.maintenance)}:{})};
 return {...base,schema:1,id:orderKey(number),fingerprint:JSON.stringify(base),sourceDraftId:o.id,source:'BAIRE VENDAS',status:'Aberto',fulfillment:'pending',createdAt:new Date().toISOString(),createdBy:currentUser?.nome||'',createdByEmail:currentUser?.email||''};
}
async function orderRequest(query,options={},retry=true){
 const controller=new AbortController();let timer;
 const token=stock?SUPA_KEY:authSession?.access_token;if(!token)throw Error('Entre novamente para enviar ou consultar os pedidos.');
 const task=(async()=>{const r=await fetch(SUPA_URL+'/rest/v1/dados'+query,{...options,headers:{apikey:SUPA_KEY,Authorization:'Bearer '+token,'Content-Type':'application/json',...(options.headers||{})},signal:controller.signal});if(r.status===401&&!stock&&retry&&typeof refreshAuth==='function'){await refreshAuth();return orderRequest(query,options,false);}const body=await r.text(),data=body?JSON.parse(body):null;if(!r.ok)throw Error('Não foi possível confirmar o pedido na base ('+r.status+').');return data;})();
 try{return await Promise.race([task,new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('A consulta do pedido demorou. Seu preenchimento foi preservado; tente novamente.'));},25000);})]);}finally{clearTimeout(timer);}
}
async function readSharedOrder(id){const rows=await orderRequest('?id=eq.'+encodeURIComponent(id)+'&select=conteudo');return rows?.[0]?.conteudo||null;}
async function submitOrder(o){
 if(stock||!allowed())throw Error('Acesso não autorizado.');
 const next=orderPayload(o),existing=await readSharedOrder(next.id);
 if(existing){if(existing.fingerprint!==next.fingerprint)throw Error('Este número já está no Baire Controle com outros dados. Confira o pedido existente antes de emitir outro.');return existing;}
 const queued=await readCustomerOrders();if(queued.some(o=>o.id!==next.id&&o.orderNumber.toUpperCase()===next.orderNumber.toUpperCase()))throw Error('Este número já está no Controle de entregas.');
 const operational=await cloudGet('vendas');if(!Array.isArray(operational))throw Error('Não foi possível conferir os pedidos já registrados. Tente novamente.');
 if(operational.some(v=>String(v.pedido||'').trim().toUpperCase()===next.orderNumber.toUpperCase()))throw Error('Este número já consta no registro de vendas. Use o número do próximo pedido.');
 await orderRequest('',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({id:next.id,conteudo:next})});
 const saved=await readSharedOrder(next.id);if(!saved||saved.fingerprint!==next.fingerprint)throw Error('A base ainda não confirmou este pedido. Tente novamente; o mesmo número não será duplicado.');return saved;
}
function writePrintWindow(p,o){p.document.open();p.document.write(printDocumentHTML(o));p.addEventListener('load',()=>{p.focus();p.print();},{once:true});p.document.close();p.focus();}
async function saveAndPrint(){
 if(!allowed()||orderSending||editing?.loadingNotes)return;
 const p=window.open('','baireOrderPrintPreview','width=980,height=780');if(!p){alert('Autorize a janela de impressão neste navegador.');return;}
 p.document.open();p.document.write('<!doctype html><meta charset="utf-8"><p>Confirmando o pedido…</p>');p.document.close();
 // Legacy imported orders remain reprintable without creating a new operational sale.
 if(editing?.originalOrder&&!editing.sentOrderId){collect();writePrintWindow(p,editing);return;}
 if(editing?.sentOrderId&&!fullEditAllowed(editing)){writePrintWindow(p,editing);return;}
 const saved=await save();if(saved)writePrintWindow(p,editing);else{p.document.open();p.document.write('<!doctype html><meta charset="utf-8"><p>Pedido não confirmado. Volte ao formulário para conferir e tentar salvar.</p>');p.document.close();}
}

async function readCustomerOrders(){
 if(stock||!allowed())throw Error('Acesso não autorizado ao histórico de pedidos.');
 const rows=[];for(let offset=0;;offset+=1000){const page=await orderRequest('?id=like.'+ORDER_PREFIX+'*&select=conteudo&order=id&limit=1000&offset='+offset);rows.push(...(page||[]));if((page||[]).length<1000)break;}
 return rows.map(r=>r.conteudo).filter(o=>o?.schema===1&&o.id?.startsWith(ORDER_PREFIX)).filter(o=>manager()||!(typeof clienteReservadoIris==='function'?clienteReservadoIris(o.client):historyReservedName(o.client)));
}
function historyReservedName(name){return norm(name).includes('DPASCHOAL')||/(^|[^A-Z0-9])(DPA|DPK)(?=$|[^A-Z0-9])/.test(String(name||'').toUpperCase());}
async function listSharedOrders(){
 if(!canManageDelivery())throw Error('Acesso não autorizado.');
 const rows=[];for(let offset=0;;offset+=1000){const page=await orderRequest('?id=like.'+ORDER_PREFIX+'*&select=conteudo&order=id&limit=1000&offset='+offset);rows.push(...(page||[]));if((page||[]).length<1000)break;}return rows.map(r=>r.conteudo).filter(o=>o?.schema===1&&o.id?.startsWith(ORDER_PREFIX)).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
}
let queueFilters={order:'',client:'',from:'',to:'',saleClass:'',status:''};
function queueStatusOptions(saleClass){if(!saleClass)return [['','Todos os status'],['pending','Pendentes'],...deliveryStatuses.map(s=>[s,'Entrega — '+s]),...maintenanceStages.map(s=>[s,'Manutenção — '+s]),['maintenance_finance','Financeiro — NF e boleto']];if(saleClass===classes[1])return [['','Todos os status de manutenção'],['pending','Pendentes — atendimento técnico'],...maintenanceStages.map(s=>[s,s]),['maintenance_finance','Financeiro — NF e boleto']];return [['','Todos os status de entrega'],['pending','Pendentes — não lançados'],...deliveryStatuses.map(s=>[s,s])];}
function queueStatusOptionsHTML(){return queueStatusOptions(queueFilters.saleClass).map(([value,label])=>'<option value="'+e(value)+'"'+(queueFilters.status===value?' selected':'')+'>'+e(label)+'</option>').join('');}
function changeQueueClass(){const input=document.getElementById('bofQueue-saleClass');queueFilters.saleClass=input?.value||'';queueFilters.status='';const status=document.getElementById('bofQueue-status');if(status){status.innerHTML=queueStatusOptionsHTML();status.value='';status.disabled=false;}applyQueueFilters();}
function filterQueueOrders(records,filters){
 const order=norm(filters.order),client=norm(filters.client),from=filters.from||'',to=filters.to||'';
 if(from&&to&&from>to)return [];
 return records.filter(o=>(!filters.saleClass||o.saleClass===filters.saleClass)&&(!order||norm(o.orderNumber).includes(order))&&(!client||norm(o.client).includes(client))&&(!from||o.date>=from)&&(!to||o.date<=to)&&(!filters.status||(filters.status==='maintenance_finance'?maintenanceFinancePending(o):filters.status==='pending'?(isMaintenance(o)?!o.maintenance?.financeDone:deliveryStatus(o)!=='Lançado'):deliveryStatus(o)===filters.status)));
}
