 return (invalid?'<p role="alert">A data inicial deve ser anterior ou igual à data final.</p>':'')+'<p role="status">'+records.length+' de '+totalCount+' pedido(s)</p><p style="font-size:12px;color:#3a526c">Clique em Alterar status para abrir uma janela com o pedido e o histórico.</p><div style="overflow:auto"><style>#bofQueueResults td,#bofQueueResults th{white-space:normal;overflow-wrap:anywhere;padding:8px 5px;vertical-align:top;font-size:13px;border-bottom:1px solid #d5e1ed}#bofQueueResults th{background:#e0ecf8;color:#174e7e;text-align:left}#bofQueueResults button{white-space:normal}</style><table style="width:100%;min-width:0;table-layout:fixed;border-collapse:collapse"><colgroup><col style="width:7%"><col style="width:25%"><col style="width:9%"><col style="width:9%"><col style="width:12%"><col style="width:14%"><col style="width:14%"><col style="width:10%"></colgroup><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Valor</th><th>Classe de venda</th><th>Status da entrega</th><th>'+e(orderHandlingHeader(records))+'</th><th>Abrir / imprimir</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+(records.length?'':'<p>'+(totalCount?'Nenhum pedido encontrado com esses filtros.':'Nenhum pedido enviado pelo Baire Vendas até o momento.')+'</p>');
